35	import org.springframework.samples.petclinic.rest.api.OwnersApi;
36	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
37	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.PetDto;
39	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitDto;
41	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
42	import org.springframework.samples.petclinic.service.ClinicService;
43	import org.springframework.security.access.prepost.PreAuthorize;
44	import org.springframework.web.bind.annotation.CrossOrigin;
45	import org.springframework.web.bind.annotation.RequestMapping;
46	import org.springframework.web.bind.annotation.RestController;
47	import org.springframework.web.util.UriComponentsBuilder;
48	
49	import jakarta.transaction.Transactional;
50	
51	/**
52	 * @author Vitaliy Fedoriv
53	 */
54	
55	@RestController
56	@CrossOrigin(exposedHeaders = "errors, content-type")
57	@RequestMapping("/api")
58	public class OwnerRestControllerV1 implements OwnersApi {
59	
60	    private final ClinicService clinicService;
61	
62	    private final OwnerMapper ownerMapper;
63	
64	    private final PetMapper petMapper;
65	
66	    private final VisitMapper visitMapper;
67	
68	    public OwnerRestControllerV1(ClinicService clinicService,
69	                                 OwnerMapper ownerMapper,
70	                                 PetMapper petMapper,
71	                                 VisitMapper visitMapper) {
72	        this.clinicService = clinicService;
73	        this.ownerMapper = ownerMapper;
74	        this.petMapper = petMapper;
75	        this.visitMapper = visitMapper;
76	    }
77	
78	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
79	    @Override
80	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
81	        Collection<Owner> owners;
82	        if (lastName != null) {
83	            owners = this.clinicService.findOwnerByLastName(lastName);
84	        } else {
85	            owners = this.clinicService.findAllOwners();
86	        }
87	        if (owners.isEmpty()) {
88	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
89	        }
90	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
91	    }
92	
93	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
94	    @Override
95	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
96	        Owner owner = this.clinicService.findOwnerById(ownerId);
97	        if (owner == null) {
98	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
99	        }
100	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
101	    }
102	
103	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
104	    @Override
105	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
106	        validateRequiredFields(ownerFieldsDto);
107	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
108	        ownerFieldsDto.setTelephone(telephone);
109	        requireUniqueTelephone(telephone);
110	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
111	        HttpHeaders headers = new HttpHeaders();
112	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
113	        this.clinicService.saveOwner(owner);
114	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
115	        headers.setLocation(UriComponentsBuilder.newInstance()
116	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
117	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
118	    }
119	
120	    /**
121	     * Rejects an owner payload that omits or leaves blank any required field. Bean Validation already rejects missing
122	     * ({@code null}) required fields, but permits values that are blank (empty or whitespace-only) for fields without a
123	     * stricter pattern, so this check enforces the "missing or blank" rule uniformly across every required field.
124	     *
125	     * @param ownerFieldsDto the owner payload to validate
126	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or telephone is missing or blank
127	     */
128	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
129	        List<String> missingFields = new ArrayList<>();
130	        requireText(missingFields, "firstName", ownerFieldsDto.getFirstName());
131	        requireText(missingFields, "lastName", ownerFieldsDto.getLastName());
132	        requireText(missingFields, "address", ownerFieldsDto.getAddress());
133	        requireText(missingFields, "city", ownerFieldsDto.getCity());
134	        requireText(missingFields, "telephone", ownerFieldsDto.getTelephone());
135	        if (!missingFields.isEmpty()) {
136	            throw new MissingOwnerFieldsException(missingFields);
137	        }
138	    }
139	
140	    private void requireText(List<String> missingFields, String fieldName, String value) {
141	        if (value == null || value.isBlank()) {
142	            missingFields.add(fieldName);
143	        }
144	    }
145	
146	    /**
147	     * Normalizes a telephone number by removing every non-digit character, then requires the result to be exactly ten
148	     * digits. The normalized 10-digit value is what gets stored and returned as {@code telephone}.
149	     *
150	     * @param telephone the raw telephone value from the request
151	     * @return the normalized 10-digit telephone
152	     * @throws InvalidTelephoneException if the value is not exactly ten digits after non-digit characters are stripped
153	     */
154	    private String normalizeTelephone(String telephone) {
155	        String digits = telephone == null ? "" : telephone.replaceAll("\\D", "");
156	        if (digits.length() != 10) {
157	            throw new InvalidTelephoneException(
158	                "telephone must contain exactly 10 digits after removing non-digit characters");
159	        }
160	        return digits;
161	    }
162	
163	    /**
164	     * Normalizes an optional owner email. A syntactically valid address is already enforced by Bean Validation on the
165	     * request payload, so this only canonicalizes the value that gets stored and returned by lower-casing it. A missing
166	     * (blank or {@code null}) email is left untouched, since the field is optional.
167	     *
168	     * @param email the raw email value from the request, may be {@code null}
169	     * @return the lower-cased email, or the original value when none was supplied
170	     */
171	    private String normalizeEmail(String email) {
172	        if (email == null || email.isBlank()) {
173	            return email;
174	        }
175	        return email.toLowerCase();
176	    }
177	
